// TH15 v1.00b Stage 4 Boss nonspell 1 (st04bs.ecl.txt::Boss1, lines 769-793).
// Card shell: invulnerable control enemy + real boss at (0,128); child enemies
// follow the invulnerable survive path (setDeath/BI3 return and flagExtDmg are
// omitted per task; birth ANIM retreat and internal asyncs are kept).
//
// Source -> card timing: card frame 0 starts the segment clock, the source
// attack t=0 lands near card frame 123 (120-frame opening buffer + task start
// offsets). TIME_LIMIT = 120 + 2400 source window + 4 startup margin.

const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

// ---------------------------------------------------------------------------
// Source Boss1_at / Boss1_at2 are async calls (thecl "@Sub()" == callAsync).
// ---------------------------------------------------------------------------
async sub boss_volley(dirsign: int) {
    // Boss1_at: %F0 starts 0, -=15deg per child, %F1=+3deg/f, %F3=-1deg/shot.
    // Boss1_at2: mirrored (+15deg, -3deg/f, +1deg/shot).
    for idx in 0..12 {
        var phase_bam: int = -(dirsign * idx * 65536 / 24);
        var omega: angle = ((dirsign * 65536) / 120) as angle;
        var bstep: int = -(dirsign * 65536 / 360);
        var i0: int = 180 - 5 * idx;
        if idx % 4 == 0 {
            // enmCreate("BCir01b", 0,0, 600,1000,0) relative to parent FINAL.
            _ = spawn_enemy($self_x, $self_y, 600, 0, 0, 0,
                            child(phase_bam, omega, i0, bstep, 1, 6));
        } else {
            // enmCreate("BCir01", 0,0, 300,1000,0).
            _ = spawn_enemy($self_x, $self_y, 300, 0, 0, 0,
                            child(phase_bam, omega, i0, bstep, 0, 2));
        }
        wait(5);
    }
}

// Source Boss1_at/Boss1_at2: 412 moveRand(60,4,1.0f) under moveLimit(0,128,280,64)
// (x in [-140,140], y in [96,160]; direction inner region x +-70, y 112..144).
sub boss_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    var ang: angle = a as angle;
    // speed(k) = 1 - k/60, k = 1..60; clamped per tick like the source limit.
    for k in 1..61 {
        var speed: fx = 0fx;
        if k < 60 { speed = (60 - k) as fx / 60fx; }
        var nx: fx = $self_x + speed * cos(ang);
        var ny: fx = $self_y + speed * sin(ang);
        if nx < -140fx { nx = -140fx; }
        if nx > 140fx { nx = 140fx; }
        if ny < 96fx { ny = 96fx; }
        if ny > 160fx { ny = 160fx; }
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
        wait(1);
    }
}

// ---------------------------------------------------------------------------
// Child enemy: BCir01 / BCir01b.
// Shared int slots: 0 = at-firing alive, 1 = published FINAL_ANGLE (BAM).
// ---------------------------------------------------------------------------
async sub child(phase_bam: int, omega: angle, i0: int, bstep: int, is_b: int, color: int) {
    set_invuln(65535);
    set_hurtbox(12fx);                       // setHurtbox(24,24)
    set_hitbox(8fx);                         // setHitbox(16,16)
    set_enemy_flag(ENEMY_NO_BODY, 1);        // flagSet(15) body-off part
    set_self_int(0, 1);
    set_self_int(1, phase_bam);
    var cx: fx = $self_x;
    var cy: fx = $self_y;
    var theta: angle = phase_bam as angle;
    spawn child_fire_a(color, bstep);        // @BCir01_at(color) async 1
    // moveCircle(phase, omega, 0, 0) + moveCircleTime(120,0,keep,100,0), then wait(120).
    var k: int = 0;
    while k < 120 {
        k = k + 1;
        theta = theta + omega;
        var r: fx = (k * 100) as fx / 120fx;
        var tx: fx = cx + r * cos(theta);
        var ty: fx = cy + r * sin(theta);
        var dx: fx = tx - $self_x;
        var dy: fx = ty - $self_y;
        set_self_int(1, atan2(dy, dx) as int);
        move_vel_xy(0, dx, dy, EASE_LINEAR);
        wait(1);
    }
    set_enemy_flag(ENEMY_NO_BODY, 0);        // flagClear(15) after 120 frames
    // wait($I0), still orbiting at r=100.
    while k < 120 + i0 {
        k = k + 1;
        theta = theta + omega;
        var tx2: fx = cx + 100fx * cos(theta);
        var ty2: fx = cy + 100fx * sin(theta);
        var dx2: fx = tx2 - $self_x;
        var dy2: fx = ty2 - $self_y;
        set_self_int(1, atan2(dy2, dx2) as int);
        move_vel_xy(0, dx2, dy2, EASE_LINEAR);
        wait(1);
    }
    move_vel(0, self_int(1) as angle, 3fx, EASE_LINEAR);   // moveVel(FINAL_ANGLE,3)
    set_self_int(0, 0);                      // killAsync(1)
    if is_b == 1 && global(GVAR_RANK) == 3 {
        spawn child_fire_b(color, bstep * 60, bstep);      // !L @BCir01_at2(6) async
    }
    loop { wait(1000); }
}

// ---------------------------------------------------------------------------
// Bullet helpers. Source etSprite(0,11,color), etCount(0,2,1), etAim(0,3)
// fixed-direction ring: base and base+180. EX type 2 ANIM a=1 only contributes
// the birth retreat position -= 4*velocity.
// ---------------------------------------------------------------------------
sub fire_one(color: int, speed: fx, ang: angle) {
    var back: fx = 4fx * speed;
    _ = fire(TH15_TALISMAN, color,
             $self_x - back * cos(ang), $self_y - back * sin(ang),
             speed, ang, none, none);
}

sub fire_pair(color: int, speed: fx, base: int) {
    fire_one(color, speed, base as angle);
    fire_one(color, speed, (base + 32768) as angle);
}

// BCir01_at: wait(10); speed 2.0 (E/N) / 2.1 (H/L); wait 12/8/6/6;
// loop count 200 (E) / 400; B starts 0 and steps by %F3.
async sub child_fire_a(color: int, bstep: int) {
    wait(10);
    var rank: int = global(GVAR_RANK);
    var speed: fx = 2fx;
    if rank >= 2 { speed = 2.1fx; }
    var period: int = 6;
    if rank == 0 {
        period = 12;
    } else if rank == 1 {
        period = 8;
    }
    var c: int = 400;
    if rank == 0 { c = 200; }
    var b: int = 0;
    while c > 0 {
        if self_int(0) == 0 { break; }
        fire_pair(color, speed, self_int(1) + b);
        b = b + bstep;
        c = c - 1;
        wait(period);
    }
}

// BCir01_at2: wait(10); speed 2.0; 100 bursts of 7 shots 5 frames apart;
// B starts at %F3*60 and steps by %F3; inter-burst wait 15 (E/N/H) / 10 (L).
async sub child_fire_b(color: int, b0: int, bstep: int) {
    wait(10);
    var tail: int = 15;
    if global(GVAR_RANK) == 3 { tail = 10; }
    var b: int = b0;
    var c: int = 100;
    while c > 0 {
        var d: int = 7;
        while d > 0 {
            fire_pair(color, 2fx, self_int(1) + b);
            b = b + bstep;
            d = d - 1;
            wait(5);
        }
        c = c - 1;
        wait(tail);
    }
}

// ---------------------------------------------------------------------------
// Source Boss1 body: timerReset/setInterrupt(0,2300,2400)/lifeMarker/stars are
// replaced by the phase shell; wait(60), then the mirrored volleys.
// ---------------------------------------------------------------------------
async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(20fx);                       // setHurtbox(40,40)
    set_hitbox(24fx);                        // setHitbox(48,48)
    wait(60);
    loop {
        spawn boss_volley(1);                // @Boss1_at()
        wait(20);
        boss_move_rand();                    // moveRand(60,4,1.0) takes 60 of the next 190
        wait(130);
        spawn boss_volley(-1);               // @Boss1_at2()
        wait(20);
        boss_move_rand();
        wait(130);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 16300, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
